// Turns each page of a PDF into what the LLM reads best from it:
// - A page with a text layer (generated by a billing system) → its exact text, rebuilt by position.
// - A page without usable text (scanned, text drawn as shapes, broken fonts) → a PNG image.
// The decision is per page: a PDF can have a digital first page and a scanned annex.
// The limits are checked while reading, so an oversized PDF is rejected before it is rendered
// (CPU and memory) or sent whole to the paid model.
using BgInventario.Core.Common;
using BgInventario.Core.Features.Invoices;
using PDFtoImage;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;

namespace BgInventario.Infrastructure.Invoices;

/// <summary>A page read either as text or as an image; exactly one of the two is set.</summary>
internal sealed record InvoicePage(int Number, string? Text, byte[]? Image);

internal static class PdfPageReader
{
    // Fewer visible letters than this means there is no real text layer (a scan may still carry a few).
    private const int MinLettersForTextPage = 20;

    // Share of letters that must be readable characters; fonts without a Unicode map produce
    // replacement or private-use characters, and then the image is more reliable than the text.
    private const double MinReadableRatio = 0.9;

    // Resolution of the pages converted to images: enough for small print without heavy images.
    private const int RenderDpi = 200;

    // An invoice is a few pages; more than this is not an invoice, or not one to read in one request.
    internal const int MaxPages = 20;

    // Text sent to the model, in characters (about 25,000 tokens): bounds the cost of one analysis.
    internal const int MaxTextCharacters = 100_000;

    /// <summary>
    /// Reads every page, or fails as soon as the PDF goes over a limit: too many pages, too much
    /// text, or more scanned pages than images the model accepts in one request.
    /// </summary>
    public static Result<List<InvoicePage>> ReadPages(byte[] pdf, int maxScannedPages)
    {
        using var document = PdfDocument.Open(pdf);
        var exceedsPageLimit = document.NumberOfPages > MaxPages;
        if (exceedsPageLimit)
        {
            return InvoiceErrors.DocumentTooLarge;
        }

        var pages = new List<InvoicePage>();
        var textCharacters = 0;
        var scannedPages = 0;

        foreach (var page in document.GetPages())
        {
            var letters = WithoutOverlappingDuplicates(page.Letters);
            if (HasUsableText(letters))
            {
                var words = NearestNeighbourWordExtractor.Instance.GetWords(letters).ToList();
                var text = PageLayoutText.Build(words);

                textCharacters += text.Length;
                var exceedsTextLimit = textCharacters > MaxTextCharacters;
                if (exceedsTextLimit)
                {
                    return InvoiceErrors.DocumentTooLarge;
                }

                pages.Add(new InvoicePage(page.Number, text, null));
            }
            else
            {
                // Checked before rendering: rendering is the expensive part.
                scannedPages++;
                var exceedsScannedLimit = scannedPages > maxScannedPages;
                if (exceedsScannedLimit)
                {
                    return InvoiceErrors.TooManyScannedPages;
                }

                var pageIndex = page.Number - 1; // PdfPig counts pages from 1, PDFtoImage from 0
                pages.Add(new InvoicePage(page.Number, null, RenderPng(pdf, pageIndex)));
            }
        }

        return pages;
    }

    /// <summary>
    /// Some generators fake bold text by drawing each letter twice at almost the same spot, which
    /// would read as "TToottaall". Letters with the same value at the same rounded position are kept once.
    /// </summary>
    private static List<Letter> WithoutOverlappingDuplicates(IReadOnlyList<Letter> letters) =>
        letters
            .DistinctBy(letter => (
                letter.Value,
                X: Math.Round(letter.StartBaseLine.X),
                Y: Math.Round(letter.StartBaseLine.Y)))
            .ToList();

    private static bool HasUsableText(IReadOnlyList<Letter> letters)
    {
        var visible = letters.Where(letter => !string.IsNullOrWhiteSpace(letter.Value)).ToList();
        if (visible.Count < MinLettersForTextPage)
        {
            return false;
        }

        var readable = visible.Count(letter => letter.Value.All(IsReadableCharacter));
        var readableRatio = readable / (double)visible.Count;
        return readableRatio >= MinReadableRatio;
    }

    /// <summary>False for the characters a PDF produces when it cannot map a glyph to a real letter.</summary>
    private static bool IsReadableCharacter(char character)
    {
        if (character == '�') // Unicode replacement character
        {
            return false;
        }

        var category = char.GetUnicodeCategory(character);
        return category is not (System.Globalization.UnicodeCategory.PrivateUse
            or System.Globalization.UnicodeCategory.Control
            or System.Globalization.UnicodeCategory.OtherNotAssigned);
    }

    private static byte[] RenderPng(byte[] pdf, int pageIndex)
    {
        // PDFium ships native binaries only for these systems; the API runs on Linux (container)
        // and is developed on any of the three. The check also tells the analyzer (CA1416).
        if (OperatingSystem.IsLinux() || OperatingSystem.IsWindows() || OperatingSystem.IsMacOS())
        {
            using var image = new MemoryStream();
            Conversion.SavePng(image, pdf, pageIndex, options: new RenderOptions { Dpi = RenderDpi });
            return image.ToArray();
        }

        throw new PlatformNotSupportedException("Rendering PDF pages requires Linux, Windows or macOS.");
    }
}

/// <summary>
/// Rebuilds a page as it looks, like `pdftotext -layout`. The order of the text inside a PDF is
/// often not the visual order, so words are placed by their coordinates instead: grouped into
/// lines by height and spaced by their horizontal position, which keeps table columns aligned:
///
///   CANT  DESCRIPCION              P.UNIT     TOTAL
///   2     MON 24 FHD               150,00    300,00
/// </summary>
internal static class PageLayoutText
{
    // Two words are on the same line when their baselines differ by less than this share of the
    // typical word height (subscripts and slightly misaligned cells stay on their line).
    private const double SameLineTolerance = 0.5;

    public static string Build(IReadOnlyList<Word> words)
    {
        var visibleWords = words.Where(word => !string.IsNullOrWhiteSpace(word.Text)).ToList();
        if (visibleWords.Count == 0)
        {
            return string.Empty;
        }

        // Average character width converts a horizontal position into a text column.
        var totalWidth = visibleWords.Sum(word => word.BoundingBox.Width);
        var totalCharacters = visibleWords.Sum(word => word.Text.Length);
        var characterWidth = Math.Max(totalWidth / totalCharacters, 1);

        var typicalHeight = visibleWords.Average(word => word.BoundingBox.Height);
        var lineTolerance = typicalHeight * SameLineTolerance;
        var pageLeft = visibleWords.Min(word => word.BoundingBox.Left);

        var lines = GroupIntoLines(visibleWords, lineTolerance);
        var renderedLines = lines.Select(line => RenderLine(line, pageLeft, characterWidth));
        return string.Join('\n', renderedLines);
    }

    /// <summary>Top to bottom; in PDF coordinates the vertical axis grows upwards.</summary>
    private static List<List<Word>> GroupIntoLines(List<Word> words, double lineTolerance)
    {
        var lines = new List<List<Word>>();
        List<Word>? currentLine = null;
        var currentBaseline = double.NaN;

        foreach (var word in words.OrderByDescending(word => word.BoundingBox.Bottom))
        {
            var startsNewLine = currentLine is null || Math.Abs(word.BoundingBox.Bottom - currentBaseline) > lineTolerance;
            if (startsNewLine)
            {
                currentLine = [];
                lines.Add(currentLine);
                currentBaseline = word.BoundingBox.Bottom;
            }

            currentLine!.Add(word);
        }

        return lines;
    }

    /// <summary>Places each word at the column of its position, with at least one space between words.</summary>
    private static string RenderLine(List<Word> line, double pageLeft, double characterWidth)
    {
        var builder = new System.Text.StringBuilder();

        foreach (var word in line.OrderBy(word => word.BoundingBox.Left))
        {
            var column = (int)Math.Round((word.BoundingBox.Left - pageLeft) / characterWidth);
            var spaces = builder.Length == 0 ? column : Math.Max(column - builder.Length, 1);
            builder.Append(' ', spaces);
            builder.Append(word.Text);
        }

        return builder.ToString();
    }
}
